/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_reverse_collection_v48` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_reverse_collection_v48`(
    IN p_or_number VARCHAR(50)
)
BEGIN
    DECLARE v_collection_id INT;


    SELECT collection_id
    INTO v_collection_id
    FROM collection
    WHERE or_number = p_or_number
    LIMIT 1;

    IF v_collection_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Collection not found';
    END IF;

    START TRANSACTION;


    UPDATE billing b
    JOIN payment p ON p.billing_id = b.billing_id
    SET
        b.remaining_water_charge = ROUND(b.remaining_water_charge + p.water_paid, 2),
        b.remaining_tax_amount = ROUND(b.remaining_tax_amount + p.tax_paid, 2),
        b.remaining_penalty_amount = ROUND(b.remaining_penalty_amount + p.penalty_paid, 2),
        b.remaining_scf_amount = ROUND(b.remaining_scf_amount + p.scf_paid, 2),
        b.remaining_balance = ROUND(b.remaining_balance + p.amount_paid, 2),

        b.payment_count = GREATEST(b.payment_count - 1, 0),


        b.status = CASE
            WHEN (b.remaining_balance + p.amount_paid) = 0 THEN 'paid'
            ELSE 'unpaid'
        END,

        b.updated_at = NOW(),
        b.updated_by_user_id = NULL

    WHERE p.collection_id = v_collection_id
      AND p.billing_id IS NOT NULL;


    UPDATE billing
    SET last_collection_id = NULL,
        last_payment_date = NULL
    WHERE last_collection_id = v_collection_id;


    DELETE FROM payment
    WHERE collection_id = v_collection_id;

    DELETE FROM collection
    WHERE collection_id = v_collection_id;

    COMMIT;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_reverse_collection_v49` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_reverse_collection_v49`(
    IN p_or_number VARCHAR(50)
)
BEGIN
    DECLARE v_collection_id INT;

    -- Get collection
    SELECT collection_id
    INTO v_collection_id
    FROM collection
    WHERE or_number = p_or_number
    LIMIT 1;

    IF v_collection_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Collection not found';
    END IF;

    START TRANSACTION;

    -- ===============================
    -- 1. REVERSE BILLING PAYMENTS
    -- ===============================
    UPDATE billing b
    JOIN payment p ON p.billing_id = b.billing_id
    SET
        b.remaining_water_charge = ROUND(b.remaining_water_charge + p.water_paid, 2),
        b.remaining_tax_amount = ROUND(b.remaining_tax_amount + p.tax_paid, 2),
        b.remaining_penalty_amount = ROUND(b.remaining_penalty_amount + p.penalty_paid, 2),
        b.remaining_scf_amount = ROUND(b.remaining_scf_amount + p.scf_paid, 2),
        b.remaining_balance = ROUND(b.remaining_balance + p.amount_paid, 2),

        b.payment_count = GREATEST(b.payment_count - 1, 0),

        b.status = CASE
            WHEN (b.remaining_balance + p.amount_paid) = 0 THEN 'paid'
            ELSE 'unpaid'
        END,

        b.updated_at = NOW(),
        b.updated_by_user_id = NULL

    WHERE p.collection_id = v_collection_id
      AND p.billing_id IS NOT NULL;

    -- ===============================
    -- 2. REVERSE SCF BALANCE (IMPORTANT)
    -- ===============================
    UPDATE scf_balance sb
    JOIN payment p ON p.collection_id = v_collection_id
    SET
        sb.balance = ROUND(sb.balance + p.scf_paid, 2),
        sb.updated_at = NOW()
    WHERE sb.concessionaire_id = (
        SELECT b.concessionaire_id
        FROM billing b
        WHERE b.billing_id = p.billing_id
        LIMIT 1
    )
    AND p.scf_paid > 0;

    -- ===============================
    -- 3. CLEAN BILLING LINKS
    -- ===============================
    UPDATE billing
    SET last_collection_id = NULL,
        last_payment_date = NULL
    WHERE last_collection_id = v_collection_id;

    -- ===============================
    -- 4. DELETE RECORDS
    -- ===============================
    DELETE FROM payment
    WHERE collection_id = v_collection_id;

    DELETE FROM collection
    WHERE collection_id = v_collection_id;

    COMMIT;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_void_billing_v1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_void_billing_v1`(
    IN p_billing_id INT,
    IN p_voided_by_user_id INT,
    IN p_void_remarks TEXT
)
sp_main: BEGIN

    DECLARE v_bill_number VARCHAR(50) DEFAULT '';

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_billing_id IS NULL OR p_billing_id <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid billing id';
    END IF;

    IF p_voided_by_user_id IS NULL OR p_voided_by_user_id <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid user id';
    END IF;

    SET p_void_remarks = COALESCE(NULLIF(TRIM(p_void_remarks), ''), 'No reason provided');

    START TRANSACTION;

    SELECT b.bill_number
    INTO v_bill_number
    FROM billing b
    WHERE b.billing_id = p_billing_id
    FOR UPDATE;

    IF v_bill_number IS NULL OR v_bill_number = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Billing record not found';
    END IF;

    -- DELETE BILLING
    DELETE FROM billing
    WHERE billing_id = p_billing_id;

    -- AUDIT LOG (clean + human readable)
    INSERT INTO user_logs (
        user_id,
        action_type,
        module,
        entity_name,
        entity_id,
        description
    )
    VALUES (
        p_voided_by_user_id,
        'VOID',
        'BILLING',
        'billing',
        p_billing_id,
        CONCAT(
            'Billing record #', v_bill_number,
            ' was voided and permanently removed from the system. ',
            'Reason: ', p_void_remarks, '.'
        )
    );

    COMMIT;

    SELECT
        p_billing_id AS billing_id,
        v_bill_number AS bill_number,
        'VOIDED' AS status;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_void_collection_v48` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_void_collection_v48`(
    IN p_collection_id INT,
    IN p_voided_by_user_id INT,
    IN p_void_remarks TEXT
)
sp_main: BEGIN

    DECLARE v_done INT DEFAULT 0;

    DECLARE v_target_collection_id INT DEFAULT 0;
    DECLARE v_collection_status VARCHAR(50) DEFAULT '';
    DECLARE v_collection_total_scf DECIMAL(12,2) DEFAULT 0.00;
    DECLARE v_concessionaire_code VARCHAR(50) DEFAULT '';

    DECLARE v_payment_id INT;
    DECLARE v_billing_id INT;

    DECLARE v_voided_payment_count INT DEFAULT 0;
    DECLARE v_scf_concessionaire_id INT DEFAULT NULL;

    DECLARE cur_payments CURSOR FOR
        SELECT p.payment_id, p.billing_id
        FROM payment p
        WHERE p.collection_id = v_target_collection_id
          AND COALESCE(p.status, 'POSTED') IN ('POSTED', 'PAID')
        FOR UPDATE;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        DROP TEMPORARY TABLE IF EXISTS tmp_affected_billing;
        RESIGNAL;
    END;

    IF p_collection_id IS NULL OR p_collection_id <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid collection id';
    END IF;

    IF p_voided_by_user_id IS NULL OR p_voided_by_user_id <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid user id';
    END IF;

    SET p_void_remarks = COALESCE(NULLIF(TRIM(p_void_remarks), ''), 'No reason provided');
    SET v_target_collection_id = p_collection_id;

    START TRANSACTION;

    SELECT
        COALESCE(c.status, ''),
        COALESCE(c.total_scf, 0.00),
        COALESCE(c.concessionaire_code, '')
    INTO
        v_collection_status,
        v_collection_total_scf,
        v_concessionaire_code
    FROM collection c
    WHERE c.collection_id = v_target_collection_id
    FOR UPDATE;

    IF v_collection_status = '' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Collection not found';
    END IF;

    IF UPPER(v_collection_status) = 'VOIDED' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Collection already voided';
    END IF;

    DROP TEMPORARY TABLE IF EXISTS tmp_affected_billing;
    CREATE TEMPORARY TABLE tmp_affected_billing (
        billing_id INT PRIMARY KEY
    );

    OPEN cur_payments;

    payment_loop: LOOP
        FETCH cur_payments INTO v_payment_id, v_billing_id;

        IF v_done = 1 THEN
            LEAVE payment_loop;
        END IF;

        INSERT IGNORE INTO tmp_affected_billing VALUES (v_billing_id);

        UPDATE payment
        SET status = 'VOIDED',
            collection_id = NULL,
            remarks = CONCAT('Voided from collection #', v_target_collection_id)
        WHERE payment_id = v_payment_id;

        SET v_voided_payment_count = v_voided_payment_count + 1;
    END LOOP;

    CLOSE cur_payments;

    -- restore billing balances
    UPDATE billing b
    JOIN tmp_affected_billing t ON t.billing_id = b.billing_id
    SET
        b.updated_at = NOW(),
        b.updated_by_user_id = p_voided_by_user_id;

    -- SCF reversal only if no payments
    IF v_voided_payment_count = 0 AND v_collection_total_scf > 0 THEN

        SELECT c.concessionaire_id
        INTO v_scf_concessionaire_id
        FROM concessionaire c
        WHERE c.concessionaire_code = v_concessionaire_code
        LIMIT 1;

        IF v_scf_concessionaire_id IS NOT NULL THEN
            UPDATE scf_balance
            SET balance = balance + v_collection_total_scf,
                updated_at = NOW()
            WHERE concessionaire_id = v_scf_concessionaire_id
            ORDER BY scf_id DESC
            LIMIT 1;
        END IF;

    END IF;

    DELETE FROM collection
    WHERE collection_id = v_target_collection_id;

    -- CLEAN AUDIT LOG
    INSERT INTO user_logs (
        user_id,
        action_type,
        module,
        entity_name,
        entity_id,
        description
    )
    VALUES (
        p_voided_by_user_id,
        'VOID',
        'COLLECTION',
        'collection',
        v_target_collection_id,
        CONCAT(
            'Collection #', v_target_collection_id,
            ' was voided and removed from the system. ',
            v_voided_payment_count, ' payment record(s) were reversed. ',
            CASE
                WHEN v_collection_total_scf > 0 THEN
                    CONCAT('SCF amount ₱', FORMAT(v_collection_total_scf, 2), ' was restored. ')
                ELSE ''
            END,
            'Account: ', v_concessionaire_code,
            '. Reason: ', p_void_remarks, '.'
        )
    );

    COMMIT;

    DROP TEMPORARY TABLE IF EXISTS tmp_affected_billing;

    SELECT
        v_target_collection_id AS collection_id,
        'VOIDED' AS status,
        v_voided_payment_count AS voided_payments;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;

